#pragma once
#include "kstationFlashStateTask.h"
namespace kstation {
class StartupInterruptSetupTask final {
public:enum class Stage{Prepare,Write,Return,Complete};Stage stage()const{return stage_;}unsigned index()const{return index_;}bool complete()const{return stage_==Stage::Complete;}uint8_t value()const{constexpr uint8_t values[]={7,0,0x88,0,0};return values[index_];}unsigned address()const{constexpr unsigned addresses[]={0xfffff2,0xfffff8,0xfffff9,0xfffff5,0xfffff4};return addresses[index_];}unsigned nextClocks(const FlashCredits&c)const{return complete()?0:stage_==Stage::Return?c.ret:stage_==Stage::Write?3+c.write:3;}template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;if(stage_==Stage::Prepare)stage_=Stage::Write;else if(stage_==Stage::Write){write(address(),value());stage_=++index_==5?Stage::Return:Stage::Prepare;}else stage_=Stage::Complete;return cost;}
private:Stage stage_=Stage::Prepare;unsigned index_=0;};
class StartupPwmTask final {
public:enum class Stage{Offset,Write,Return,Complete};explicit StartupPwmTask(uint8_t value=0):value_(value){}Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned nextClocks(const FlashCredits&c)const{return complete()?0:stage_==Stage::Return?c.ret:stage_==Stage::Write?3+c.write:3;}template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;if(stage_==Stage::Offset)value_+=0x40;else if(stage_==Stage::Write)write(value_);stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::Offset;uint8_t value_;};
class StartupTimerSetupTask final {
public:enum class Stage{SyncValue,WriteSync,ModeValue,WriteMode,BindZeroCounter,ZeroCounterValue,WriteZeroCounter,BindPwmPeriod,PwmPeriodValue,WritePwmPeriod,PwmValue,PwmChild,ForceValue,WriteForce,OutputValue,WriteOutput,PolarityValue,WritePolarity,BindPanelPeriod,PanelPeriodValue,WritePanelPeriod,PanelControlValue,WritePanelControl,PanelIoValue,WritePanelIo,PanelInterruptValue,WritePanelInterrupt,BindTickPeriod,TickPeriodValue,WriteTickPeriod,TickControlValue,WriteTickControl,TickInterruptValue,WriteTickInterrupt,StartValue,WriteStart,BindClock,ClearClock,WriteClock,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}bool awaiting()const{return waiting_;}void resume(){waiting_=false;}unsigned width()const{return stage_==Stage::WriteClock?4:stage_==Stage::WriteZeroCounter||stage_==Stage::WritePwmPeriod||stage_==Stage::WritePanelPeriod||stage_==Stage::WriteTickPeriod?2:1;}unsigned address()const{switch(stage_){case Stage::WriteSync:return 0xffff61;case Stage::WriteMode:return 0xffff62;case Stage::WriteZeroCounter:return 0xffff6a;case Stage::WritePwmPeriod:return 0xffff6c;case Stage::WriteForce:return 0xffff63;case Stage::WriteOutput:return 0xffff90;case Stage::WritePolarity:return 0xffff91;case Stage::WritePanelPeriod:return 0xffff74;case Stage::WritePanelControl:return 0xffff6e;case Stage::WritePanelIo:return 0xffff6f;case Stage::WritePanelInterrupt:return 0xffff70;case Stage::WriteTickPeriod:return 0xffff7c;case Stage::WriteTickControl:return 0xffff82;case Stage::WriteTickInterrupt:return 0xffff84;case Stage::WriteStart:return 0xffff60;case Stage::WriteClock:return 0xfffd20;default:return 0;}}unsigned value()const{switch(stage_){case Stage::SyncValue:case Stage::WriteSync:case Stage::ZeroCounterValue:case Stage::WriteZeroCounter:case Stage::ForceValue:case Stage::WriteForce:case Stage::OutputValue:case Stage::WriteOutput:case Stage::PanelIoValue:case Stage::WritePanelIo:case Stage::ClearClock:case Stage::WriteClock:return 0;case Stage::ModeValue:case Stage::WriteMode:return 0x41;case Stage::BindZeroCounter:return 0xffff6a;case Stage::BindPwmPeriod:return 0xffff6c;case Stage::PwmPeriodValue:case Stage::WritePwmPeriod:return 30000;case Stage::PwmValue:return 0x40;case Stage::PolarityValue:case Stage::WritePolarity:return 255;case Stage::BindPanelPeriod:return 0xffff74;case Stage::PanelPeriodValue:case Stage::WritePanelPeriod:return 8000;case Stage::PanelControlValue:case Stage::WritePanelControl:return 0x20;case Stage::PanelInterruptValue:case Stage::WritePanelInterrupt:return 1;case Stage::BindTickPeriod:return 0xffff7c;case Stage::TickPeriodValue:case Stage::WriteTickPeriod:return 2;case Stage::TickControlValue:case Stage::WriteTickControl:return 3;case Stage::TickInterruptValue:case Stage::WriteTickInterrupt:return 4;case Stage::StartValue:case Stage::WriteStart:return 15;case Stage::BindClock:return 0xfffd20;default:return 0;}}
 unsigned nextClocks(const FlashCredits&c)const{if(waiting_||complete())return 0;if(address())return (width()==4?6:3)+c.write;switch(stage_){case Stage::BindZeroCounter:case Stage::BindPwmPeriod:case Stage::BindPanelPeriod:case Stage::BindTickPeriod:case Stage::BindClock:return 9;case Stage::ZeroCounterValue:case Stage::PwmPeriodValue:case Stage::PanelPeriodValue:case Stage::TickPeriodValue:return 6;case Stage::PwmChild:return c.shortCall;case Stage::Return:return c.ret;default:return 3;}}
 template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;if(address())write(address(),width(),value());if(stage_==Stage::PwmChild)waiting_=true;stage_=Stage(unsigned(stage_)+1);return cost;}
private:Stage stage_=Stage::SyncValue;bool waiting_=false;};
class StartupSerialSetupTask final {
public:enum class Stage{Prepare,Write,Retain,DelayValue,Decrement,Repeat,Restore,Return,Complete};Stage stage()const{return stage_;}bool complete()const{return stage_==Stage::Complete;}unsigned index()const{return index_;}unsigned value()const{return index_==2?15:0;}unsigned address()const{return index_==0?0xffffb2:index_==1?0xffffb0:0xffffb1;}unsigned nextClocks(const FlashCredits&c)const{switch(stage_){case Stage::Write:return 3+c.write;case Stage::Retain:return c.pushWord;case Stage::DelayValue:return 6;case Stage::Restore:return c.popWord;case Stage::Return:return c.ret;case Stage::Complete:return 0;default:return 3;}}
 template<class W>unsigned advanceBefore(unsigned budget,const FlashCredits&c,W&&write){auto cost=nextClocks(c);if(!cost||cost>budget)return 0;auto next=Stage(unsigned(stage_)+1);switch(stage_){case Stage::Write:write(address(),value());if(++index_<3)next=Stage::Prepare;break;case Stage::DelayValue:remaining_=100;break;case Stage::Decrement:--remaining_;break;case Stage::Repeat:if(remaining_)next=Stage::Decrement;break;default:break;}stage_=next;return cost;}
private:Stage stage_=Stage::Prepare;unsigned index_=0,remaining_=0;};
}
